//! Parity of the multi-step look-ahead acquisition function (phase 8b)
//! with BoTorch (fixtures in `tests/fixtures/8b-acquisition-rest/*.json`,
//! generated by `scripts/generate_fixtures.py --phase 8b-acquisition-rest`
//! against BoTorch main, with BoTorch's base samples recorded):
//!
//! * `qMultiStepLookahead` on the phase-8 models (single-output RBF,
//!   Matern-5/2 with `Normalize`, fixed noise, no outcome transform,
//!   two-output `SingleTaskGP`, `ModelListGP`): two and three steps, `q_j =
//!   2`, stage value functions (qEI and EI with `best_f` from the model,
//!   UCB), pending points, fantasy weights, posterior transforms, MC
//!   objectives, `collapse_fantasy_base_samples=False`;
//! * `optimize_acqf` of a two-step look-ahead from BoTorch's initial
//!   conditions.
//!
//! The gradients are those of a corrected BoTorch (test caches not detached,
//! no `fast_pred_var`; BoTorch's own are wrong, see the draft), and `best_f`
//! from the model is the best untransformed target (BoTorch's `make_best_f`
//! takes the outcome-transformed one). Tolerances: values 1e-9, gradients
//! 1e-8 (relative to the largest component, entries within 1e-14 count as
//! equal). `optimize_acqf`: all but one restart reach BoTorch's value within
//! 1e-6, with candidates within 1e-3. Run with `--nocapture` to print the
//! error tables.

mod common;

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::multi_step_lookahead::{
    QMultiStepLookahead, QMultiStepLookaheadOptions, StageValueFunction,
};
use botorch_core::acquisition::{
    AcquisitionFunction, KgValueFunction, LinearMcObjective, SampleUtility,
    ScalarizedPosteriorTransform,
};
use botorch_core::optim::optimize_acqf_detailed;
use botorch_core::{
    BatchedInputTransform, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, KernelKind, Matrix,
    Model, ModelListGP, Normalize, OptimizeAcqfOptions, OutcomeTransformChoice,
    SobolQMCNormalSampler, Vector,
};
use common::{matrix, matrix_rows, Report};
use serde::Deserialize;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const GRAD_ATOL: f64 = 1e-14;
const OPT_TOL: f64 = 1e-6;
/// The seed of samplers whose base samples are installed explicitly.
const SEED: u64 = 4242;

// ---------------------------------------------------------------------------
// Fixture format
// ---------------------------------------------------------------------------

/// A number of a fixture; the writer encodes non-finite numbers as strings.
#[derive(Debug, Clone, Copy)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Raw {
            F(f64),
            S(String),
        }
        Ok(F(match Raw::deserialize(d)? {
            Raw::F(v) => v,
            Raw::S(s) => match s.as_str() {
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                "nan" => f64::NAN,
                other => return Err(serde::de::Error::custom(format!("not a number: {other}"))),
            },
        }))
    }
}

fn fvec(v: &[F]) -> Vec<f64> {
    v.iter().map(|x| x.0).collect()
}

#[derive(Debug, Deserialize)]
struct Config {
    d: usize,
    m: usize,
    covar: String,
    normalize: Option<String>,
    outcome: String,
}

#[derive(Debug, Deserialize)]
struct ModelSpec {
    config: Config,
    train_x: Vec<Vec<Vec<f64>>>,
    train_y: Vec<Vec<Vec<f64>>>,
    train_yvar: Option<Vec<Vec<Vec<f64>>>>,
    raw_params: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Eval {
    x: Vec<Vec<Vec<f64>>>,
    values: Vec<F>,
    grads: Vec<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct Stage {
    name: String,
    kwargs: HashMap<String, f64>,
    best_f_from_model: bool,
    inner_base_samples: Option<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct Msl {
    name: String,
    batch_sizes: Vec<usize>,
    base_samples: Vec<Vec<Vec<f64>>>,
    weights: Option<Vec<Vec<f64>>>,
    stages: Vec<Option<Stage>>,
    transform: Option<Vec<f64>>,
    objective: Option<Vec<f64>>,
    pending: Option<Vec<Vec<f64>>>,
    collapse: bool,
    eval: Eval,
}

#[derive(Debug, Deserialize)]
struct Optimize {
    batch_sizes: Vec<usize>,
    base_samples: Vec<Vec<Vec<f64>>>,
    bounds: Vec<Vec<f64>>,
    initial_conditions: Vec<Vec<Vec<f64>>>,
    candidates: Vec<Vec<Vec<f64>>>,
    values: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    name: String,
    kind: String,
    models: Vec<ModelSpec>,
    msl: Vec<Msl>,
    optimize: Option<Optimize>,
}

fn fixture_dir() -> PathBuf {
    common::fixture_dir().join("8b-acquisition-rest")
}

fn load() -> Vec<Fixture> {
    let mut out = Vec::new();
    let mut paths: Vec<_> = std::fs::read_dir(fixture_dir())
        .expect("phase-8b fixtures (scripts/generate_fixtures.py --phase 8b-acquisition-rest)")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    for p in paths {
        let text = std::fs::read_to_string(&p).unwrap();
        out.push(serde_json::from_str(&text).unwrap_or_else(|e| panic!("{p:?}: {e}")));
    }
    assert!(!out.is_empty(), "no phase-8b fixtures");
    out
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

fn build_member(f: &ModelSpec) -> BatchedMultiOutputGP {
    let c = &f.config;
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        other => panic!("unknown covar {other}"),
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let mut model = BatchedMultiOutputGP::new(x, y, vec![], options).unwrap();
    assert_eq!(model.num_outputs(), c.m);
    model.set_raw_parameters(&f.raw_params).unwrap();
    model
}

fn build_model(f: &Fixture) -> Arc<dyn Model> {
    let members: Vec<BatchedMultiOutputGP> = f.models.iter().map(build_member).collect();
    match f.kind.as_str() {
        "single_task" => Arc::new(members.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(members).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

fn sampler(base: &[Vec<f64>]) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(base.len(), Some(SEED)).unwrap();
    s.set_base_samples(matrix(base)).unwrap();
    Arc::new(s)
}

/// The value function of a stage (the native classes of BoTorch's
/// `valfunc_cls` used by the fixtures).
fn stage(s: &Stage) -> StageValueFunction {
    let kw = |k: &str| s.kwargs.get(k).copied();
    let kind = match s.name.as_str() {
        "PosteriorMean" => KgValueFunction::PosteriorMean { maximize: true },
        "UpperConfidenceBound" => KgValueFunction::UpperConfidenceBound {
            beta: kw("beta").unwrap(),
            maximize: true,
        },
        "ExpectedImprovement" => KgValueFunction::ExpectedImprovement {
            best_f: kw("best_f").unwrap_or(0.0),
            maximize: true,
        },
        "qExpectedImprovement" => KgValueFunction::MonteCarlo(SampleUtility::ExpectedImprovement {
            best_f: kw("best_f").unwrap_or(0.0),
        }),
        "qSimpleRegret" => KgValueFunction::MonteCarlo(SampleUtility::SimpleRegret),
        other => panic!("unknown value function {other}"),
    };
    StageValueFunction {
        kind,
        best_f_from_model: s.best_f_from_model,
        sampler: s.inner_base_samples.as_ref().map(|z| sampler(z)),
    }
}

fn build_msl(model: &Arc<dyn Model>, c: &Msl) -> QMultiStepLookahead {
    QMultiStepLookahead::new(
        Arc::clone(model),
        QMultiStepLookaheadOptions {
            batch_sizes: c.batch_sizes.clone(),
            samplers: Some(c.base_samples.iter().map(|z| sampler(z)).collect()),
            sample_weights: c
                .weights
                .as_ref()
                .map(|w| w.iter().map(|v| Some(v.clone())).collect())
                .unwrap_or_default(),
            value_functions: Some(c.stages.iter().map(|s| s.as_ref().map(stage)).collect()),
            objective: c.objective.as_ref().map(|w| {
                Arc::new(LinearMcObjective::new(Vector::from_vec(w.clone())).unwrap())
                    as Arc<dyn botorch_core::acquisition::McObjective>
            }),
            posterior_transform: c.transform.as_ref().map(|w| {
                ScalarizedPosteriorTransform::new(Vector::from_vec(w.clone()), 0.0).unwrap()
            }),
            x_pending: c.pending.as_ref().map(|p| matrix(p)),
            collapse_fantasy_base_samples: c.collapse,
            ..Default::default()
        },
    )
    .unwrap()
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[test]
fn parity_multi_step_lookahead() {
    let mut r = Report::default();
    for f in load() {
        let model = build_model(&f);
        for c in &f.msl {
            let acqf = build_msl(&model, c);
            let mut values = Vec::new();
            let mut grads = Vec::new();
            for x in &c.eval.x {
                let (v, g) = acqf.forward_with_grad(&matrix(x)).unwrap();
                values.push(v);
                grads.extend(matrix_rows(&g));
                // `forward` agrees with `forward_with_grad`.
                assert_eq!(acqf.forward(&matrix(x)).unwrap(), v);
            }
            let name = format!("qMultiStepLookahead {}", c.name);
            r.check_slices(
                &f.name,
                &format!("{name} values"),
                &values,
                &fvec(&c.eval.values),
                VALUE_TOL,
            );
            let expected: Vec<f64> = c.eval.grads.iter().flatten().flatten().copied().collect();
            r.check_slices_atol(
                &f.name,
                &format!("{name} gradients"),
                &grads,
                &expected,
                GRAD_TOL,
                GRAD_ATOL,
            );
        }
    }
    r.finish("qMultiStepLookahead vs BoTorch (corrected gradients)");
}

#[test]
fn parity_optimize_multi_step_lookahead() {
    let mut r = Report::default();
    for f in load() {
        let Some(c) = &f.optimize else { continue };
        let model = build_model(&f);
        let acqf = QMultiStepLookahead::new(
            Arc::clone(&model),
            QMultiStepLookaheadOptions {
                batch_sizes: c.batch_sizes.clone(),
                samplers: Some(c.base_samples.iter().map(|z| sampler(z)).collect()),
                ..Default::default()
            },
        )
        .unwrap();
        let options = OptimizeAcqfOptions {
            batch_initial_conditions: Some(
                c.initial_conditions.iter().map(|b| matrix(b)).collect(),
            ),
            lbfgsb: botorch_core::lbfgsb::LbfgsbOptions {
                maxiter: 200,
                ..Default::default()
            },
            ..Default::default()
        };
        let q_aug = c.initial_conditions[0].len();
        let k = c.values.len();
        let res = optimize_acqf_detailed(&acqf, &matrix(&c.bounds), q_aug, k, 0, &options).unwrap();
        // BoTorch's optimize_acqf is called with the augmented size and
        // returns the candidates.
        assert_eq!(res.candidates.nrows(), 1);
        let d = c.bounds[0].len();
        let mut agree = 0;
        let mut worst_x: f64 = 0.0;
        for (i, restart) in res.restarts.iter().enumerate() {
            let e = c.values[i];
            if (restart.acq_value - e).abs() <= OPT_TOL * e.abs().max(1.0) {
                agree += 1;
                let ex: Vec<f64> = c.candidates[i].iter().flatten().copied().collect();
                let x = matrix_rows(&restart.candidates);
                worst_x = worst_x.max(common::rel_err(&x[..d], &ex[..d]));
            }
        }
        r.check(
            &f.name,
            "optimize_acqf qMultiStepLookahead: restarts below BoTorch's value",
            (k - agree) as f64,
            1.0,
        );
        r.check(
            &f.name,
            "optimize_acqf qMultiStepLookahead: candidates (agreeing restarts)",
            worst_x,
            1e-3,
        );
    }
    r.finish("optimize_acqf of qMultiStepLookahead from BoTorch's initial conditions");
}
